function timerLabel(seconds){if(seconds<60)return seconds+'s';if(seconds<3600)return Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');return Math.floor(seconds/3600)+'h '+Math.floor(seconds%3600/60)+'m';}
