function allocationAmount(allocation,currency){const fraction=allocation.fractionalAtomic;if(!fraction||fraction.numerator==='0')return currencyAmount(allocation.amountAtomic,currency);const remainder=fraction.numerator+'/'+fraction.denominator+' of '+currencyAmount('1',currency);return allocation.amountAtomic==='0'?remainder:currencyAmount(allocation.amountAtomic,currency)+' + '+remainder;}
