  const disclosure=document.createElement('p');disclosure.className='preview-disclosure';disclosure.textContent=funded?fundingDisclosure(tournament)+' Only verified claims below confirm a payment.':'Unfunded prize accounting · No funds collected or paid';resultRoot.append(disclosure);
