function renderLastRound(){const root=$('round-result'),round=current.lastRound;root.replaceChildren();root.hidden=!round;if(!round)return;const h=document.createElement('h3');h.textContent='Round '+round.roundNumber+' results';root.append(h);for(const result of round.results||[]){const award=result.awards?.find(a=>a.playerId===(credentials.role==='watcher'?current.watchingPlayerId:credentials.playerId));if(!award)continue;const p=document.createElement('p');p.textContent=(award.outcome||result.result)+' · −'+award.damage+' commander HP · +'+award.xpGranted+' XP · +'+award.treasureGold+' treasure gold'+(award.zoneGold?' · +'+award.zoneGold+' zone gold':'')+(award.itemDrop?' · +'+(current.itemCatalog?.components?.find(item=>item.id===award.itemDrop)?.name||'component'):'')+(award.cherubItems?.length?' · Cherub: '+award.cherubItems.map(id=>current.itemCatalog?.components?.find(item=>item.id===id)?.name||'component').join(', '):'')+(award.encounterItem?' · Supply encounter: '+(current.itemCatalog?.components?.find(item=>item.id===award.encounterItem)?.name||'component'):'');root.append(p);}const eliminated=players().filter(p=>p.eliminatedRound===round.roundNumber);if(eliminated.length){const p=document.createElement('p');p.textContent='Eliminated: '+eliminated.map(p=>p.name).join(', ')+'. Their armies and offers returned before preparation draws.';root.append(p);}}
function mirror(unit,board){const result=clone(unit),position=p=>{if(p&&Number.isFinite(p.col)&&Number.isFinite(p.row)){p.col=board.columns-1-p.col;p.row=board.rows-1-p.row;}};position(result);if(Number.isFinite(result.originCol))result.originCol=board.columns-1-result.originCol;if(Number.isFinite(result.originRow))result.originRow=board.rows-1-result.originRow;if(result.lastMove){position(result.lastMove.from);position(result.lastMove.to);}if(result.side)result.side=result.side==='player'?'enemy':'player';return result;}
function mirrorZones(defense,board){if(!defense)return defense;return {...clone(defense),zones:defense.zones.map(z=>({...clone(z),rect:{left:board.columns-1-z.rect.right,right:board.columns-1-z.rect.left,top:board.rows-1-z.rect.bottom,bottom:board.rows-1-z.rect.top}}))};}
