function pushRenderer(message){if(!rendererReady)return;try{const render=renderProjection();if(render)frame.contentWindow.postMessage({type:'party-view',render,pending:!!pending,connected,...(message?{message}:{})},location.origin);else frame.contentWindow.postMessage({type:'party-status',pending:!!pending,connected,...(message?{message}:{})},location.origin);}catch(error){notice('The battlefield could not display this room update: '+error.message,true);}}
function renderRoomBrowser(rooms){
  const root=$('room-browser-list');root.replaceChildren();
  $('room-browser-status').textContent=rooms.length?rooms.length+' table'+(rooms.length===1?'':'s')+' available to join or watch.':'No active tables yet. Create one to invite other players.';
  if(!rooms.length){const empty=document.createElement('p');empty.className='table-empty';empty.textContent='No rooms are open right now.';root.append(empty);return;}
  for(const table of rooms){
    const card=document.createElement('article');card.className='table-card '+table.type+(table.wager?' prize':'');
    const top=document.createElement('div');top.className='table-top';const title=document.createElement('h3');title.textContent=(table.type==='duel'?'⚔ Duel':table.type==='tournament'?'🏆 Tournament':'♟ Party')+' table';
    const count=document.createElement('strong');count.textContent=table.players.length+' / '+table.capacity;count.setAttribute('aria-label',table.players.length+' occupied seats of '+table.capacity);top.append(title,count);card.append(top);
    const badges=document.createElement('div');badges.className='table-badges';
    const labels=[table.rulesPreset==='ancient'?'◌ Ancient':table.rulesPreset==='custom'?'◈ Custom':table.rulesPreset==='original'?'○ Original':'✦ Modern',table.wager?'◈ Wager · '+table.wager.entryFee+' '+table.wager.currency+' · '+table.wager.network:'◇ Free',table.aiFill?'🤖 AI fill':'♙ Human only',table.phase==='lobby'?'○ Waiting':'● Live'];
    for(const label of labels){const badge=document.createElement('span');badge.className='table-badge'+(label.includes('Wager')?' wager':'');badge.textContent=label;badges.append(badge);}card.append(badges);
    const seats=document.createElement('div');seats.className='seat-strip';seats.setAttribute('aria-label',table.players.length+' occupied, '+table.openSeats+' open seats');
    for(let i=0;i<table.capacity;i++){const dot=document.createElement('span');const player=table.players[i];dot.className='seat-dot'+(player?player.isAI?' ai':' taken':'');dot.textContent=player?player.isAI?'A':'●':'+';dot.title=player?player.name+' seat':'Open seat';seats.append(dot);}card.append(seats);
    const roster=document.createElement('ul');roster.className='table-players';for(const player of table.players){const row=document.createElement('li'),name=document.createElement('strong'),score=document.createElement('small');name.textContent=player.name+(player.isAI?' · AI':'');score.textContent=player.wins+' W · '+player.losses+' L';row.append(name,score);roster.append(row);}card.append(roster);
    const meta=document.createElement('p');meta.className='table-meta';meta.textContent=table.openSeats+' open seat'+(table.openSeats===1?'':'s')+' · '+table.watcherCount+' watching';card.append(meta);
    const actions=document.createElement('div');actions.className='table-actions';
    if(table.openSeats>0){const join=document.createElement('button');join.type='button';join.textContent='Join table';join.setAttribute('aria-label','Join '+table.type+' room '+table.roomCode);join.onclick=()=>{$('room-code').value=table.roomCode;clearJoinPreview();$('join-form').scrollIntoView({behavior:'smooth',block:'center'});if($('join-name').value.trim())$('join-form').requestSubmit();else $('join-name').focus();};actions.append(join);}
    const watch=document.createElement('button');watch.type='button';watch.textContent='Watch';watch.setAttribute('aria-label','Watch '+table.type+' room '+table.roomCode);watch.onclick=()=>{$('room-code').value=table.roomCode;clearJoinPreview();$('join-form').scrollIntoView({behavior:'smooth',block:'center'});if($('join-name').value.trim())$('watch-room').click();else $('join-name').focus();};actions.append(watch);card.append(actions);root.append(card);
  }
}
